/// Returns the localized string for [key]. Falls back to
/// [enFallback] when language is English or key is missing.
String trContent(String key, String enFallback) {
  if (AppI18n.current != DisplayLang.zh) return enFallback;
  return contentStringsZh[key] ?? enFallback;
}
